import unittest
import math
from candidate import has_close_elements

class TestHasCloseElements(unittest.TestCase):
    def test_normal_case_no_close(self):
        self.assertFalse(has_close_elements([1.0, 2.0, 3.0], 0.5))

    def test_normal_case_with_close(self):
        self.assertTrue(has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3))

    def test_empty_list_returns_false(self):
        self.assertFalse(has_close_elements([], 0.1))

    def test_single_element_returns_false(self):
        self.assertFalse(has_close_elements([5.0], 0.1))

    def test_identical_elements_threshold_positive(self):
        self.assertTrue(has_close_elements([2.0, 2.0], 0.1))

    def test_identical_elements_threshold_zero(self):
        self.assertFalse(has_close_elements([2.0, 2.0], 0.0))

    def test_exact_threshold_distance_returns_false(self):
        self.assertFalse(has_close_elements([0.0, 1.0], 1.0))

    def test_exceeds_threshold_returns_true(self):
        self.assertTrue(has_close_elements([0.0, 1.0], 1.1))

    def test_very_small_distance(self):
        self.assertTrue(has_close_elements([0.0, 1e-10], 1e-9))

    def test_precision_edge(self):
        self.assertFalse(has_close_elements([0.0, 1e-10], 1e-10))

    def test_multiple_calls_deterministic(self):
        result1 = has_close_elements([1.0, 2.0, 3.0], 0.5)
        result2 = has_close_elements([1.0, 2.0, 3.0], 0.5)
        self.assertEqual(result1, result2)

    def test_non_list_iterable_tuple(self):
        self.assertFalse(has_close_elements((1.0, 3.0, 5.0), 0.5))

    def test_set_iterable(self):
        self.assertTrue(has_close_elements({1.0, 1.5}, 0.6))

    def test_generator_iterable(self):
        gen = (x for x in [1.0, 2.0, 2.05])
        self.assertTrue(has_close_elements(gen, 0.1))

    def test_string_iterable_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements("ab", 1.0)

    def test_none_numbers_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements(None, 0.1)

    def test_none_threshold_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements([1.0, 2.0], None)

    def test_numbers_with_nan(self):
        self.assertFalse(has_close_elements([float('nan'), 1.0, 2.0], 0.5))

    def test_numbers_with_inf(self):
        self.assertFalse(has_close_elements([float('inf'), float('-inf'), 0.0], 1e308))

    def test_large_numbers(self):
        self.assertFalse(has_close_elements([1e308, -1e308], 1e307))

    def test_threshold_negative(self):
        self.assertFalse(has_close_elements([1.0, 2.0], -0.1))

    def test_numbers_with_mixed_types_error(self):
        with self.assertRaises(TypeError):
            has_close_elements([1.0, "a"], 0.1)

    def test_threshold_as_string_error(self):
        with self.assertRaises(TypeError):
            has_close_elements([1.0, 2.0], "0.1")

if __name__ == "__main__":
    unittest.main()
